package com.multideporte.backend.standing.tiebreak.service;
import com.multideporte.backend.common.exception.BusinessException; import com.multideporte.backend.security.user.CurrentUserService; import com.multideporte.backend.standing.tiebreak.dto.StandingTieBreakDrawRequest; import com.multideporte.backend.standing.tiebreak.entity.StandingTieBreakDraw; import com.multideporte.backend.standing.tiebreak.repository.StandingTieBreakDrawRepository; import java.time.OffsetDateTime; import java.util.HashSet; import java.util.List; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class StandingTieBreakDrawService { private final StandingTieBreakDrawRepository repository; private final CurrentUserService currentUserService;
@Transactional public StandingTieBreakDraw record(StandingTieBreakDrawRequest request) { if(request.affectedTeamIds().size()<2 || !new HashSet<>(request.affectedTeamIds()).equals(new HashSet<>(request.resultingOrderTeamIds())) || new HashSet<>(request.affectedTeamIds()).size()!=request.affectedTeamIds().size()) throw new BusinessException("TIEBREAK_DRAW_INVALID: equipos y orden deben contener exactamente los mismos participantes sin duplicados"); StandingTieBreakDraw draw=new StandingTieBreakDraw(); draw.setTournamentId(request.tournamentId()); draw.setStageId(request.stageId()); draw.setGroupId(request.groupId()); draw.setAffectedTeamIds(List.copyOf(request.affectedTeamIds())); draw.setResultingOrderTeamIds(List.copyOf(request.resultingOrderTeamIds())); draw.setReason(request.reason().trim()); draw.setRecordedByUserId(currentUserService.requireCurrentUserId()); draw.setRecordedAt(OffsetDateTime.now()); return repository.save(draw); }}
